11	// ============================================================
12	// Split 算子 op_host
13	// 将输入沿 dim 拆分为 K 个 chunk，输出为 1D flat 拼接
14	// ============================================================
15	
16	#include "torch_kernel_helper.h"
17	#include "tiling/platform/platform_ascendc.h"
18	#include "aclrtlaunch_split_half.h"
19	#include "aclrtlaunch_split_float.h"
20	
21	namespace ascend_kernel {
22	
23	constexpr int64_t MAX_CHUNKS = 64;
24	
25	struct SplitTilingData {
26	    int64_t totalSegments;
27	    int64_t outerSize;
28	    int64_t innerSize;
29	    int64_t dimSize;
30	    int64_t dtypeSize;
31	
32	    int64_t numChunks;
33	    int64_t chunkSizes[MAX_CHUNKS];
34	    int64_t cumChunkOffsets[MAX_CHUNKS + 1];
35	    int64_t cumOutputOffsets[MAX_CHUNKS + 1];
36	
37	    int64_t tileLength;
38	    int64_t coreNum;
39	};
40	
41	at::Tensor split(const at::Tensor &x,
42	                 at::IntArrayRef split_sizes,
43	                 int64_t dim) {
44	    // ---- 1. 参数校验 ----
45	    TORCH_CHECK(x.device().is_privateuseone(), "split: x must be on NPU device");
46	    TORCH_CHECK(x.is_contiguous(), "split: x must be contiguous");
47	    TORCH_CHECK(x.scalar_type() == at::kFloat ||
48	                x.scalar_type() == at::kHalf ||
49	                x.scalar_type() == at::kBFloat16,
50	                "split: only float32, float16, bfloat16 are supported");
51	
52	    int64_t ndim = x.dim();
53	    if (dim < 0) dim += ndim;
54	    TORCH_CHECK(dim >= 0 && dim < ndim,
55	                "split: dim out of range, got dim=", dim);
56	
57	    int64_t K = split_sizes.size();
58	    TORCH_CHECK(K <= MAX_CHUNKS,
59	                "split: too many chunks (", K, "), max is ", MAX_CHUNKS);
60	
61	    // ---- 2. 计算维度参数 ----
62	    int64_t outerSize = 1;
63	    for (int64_t i = 0; i < dim; ++i) {
64	        outerSize *= x.size(i);
65	    }
66	    int64_t dimSize = x.size(dim);
67	    int64_t innerSize = 1;
68	    for (int64_t i = dim + 1; i < ndim; ++i) {
69	        innerSize *= x.size(i);
70	    }
71	    int64_t totalSegments = outerSize * dimSize;
72	    int64_t totalElements = totalSegments * innerSize;
73	
74	    // ---- 3. 计算 chunk 累计偏移 ----
75	    int64_t chunkSizes[MAX_CHUNKS] = {0};
76	    int64_t cumChunkOffsets[MAX_CHUNKS + 1] = {0};
77	    int64_t cumOutputOffsets[MAX_CHUNKS + 1] = {0};
78	
79	    int64_t sumChunk = 0;
80	    int64_t sumOutput = 0;
81	    for (int64_t i = 0; i < K; ++i) {
82	        int64_t sz = split_sizes[i];
83	        chunkSizes[i] = sz;
84	        cumChunkOffsets[i] = sumChunk;
85	        cumOutputOffsets[i] = sumOutput;
86	        sumChunk += sz;
87	        sumOutput += outerSize * sz * innerSize;
88	    }
89	    cumChunkOffsets[K] = sumChunk;
90	    cumOutputOffsets[K] = sumOutput;
91	
92	    TORCH_CHECK(sumChunk == dimSize,
93	                "split: sum of split_sizes (", sumChunk,
94	                ") != dim size (", dimSize, ")");
95	
96	    // ---- 4. 平台参数 ----
97	    auto platform = platform_ascendc::PlatformAscendCManager::GetInstance();
98	    int64_t coreNum = static_cast<int64_t>(platform->GetCoreNumAiv());
99	    uint64_t ubSize;
100	    platform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);
101	
102	    int64_t dtypeSize = static_cast<int64_t>(x.element_size());
103	
104	    // ---- 5. Tiling 计算 ----
105	    // bufferCoefficient = 2: VECOUT only, double buffer, no compute buffer
106	    int64_t bufferCoefficient = 2;
107	    int64_t alignElements = 32 / dtypeSize;
108	    int64_t maxTileElements = static_cast<int64_t>(ubSize) / (bufferCoefficient * dtypeSize);
109	    int64_t tileLength = (maxTileElements / alignElements) * alignElements;
110	    if (tileLength < alignElements) tileLength = alignElements;
111	
112	    // ---- 6. 创建输出 tensor (1D flat) ----
113	    auto output = at::empty({totalElements}, x.options());
114	
115	    // ---- 7. 填充 workspace (tiling data) ----
116	    auto tilingCpu = at::empty(
117	        {static_cast<int64_t>(sizeof(SplitTilingData))},
118	        at::device(at::kCPU).dtype(at::kByte));
119	    auto *tiling = reinterpret_cast<SplitTilingData *>(tilingCpu.data_ptr());
120	
121	    tiling->totalSegments = totalSegments;
122	    tiling->outerSize     = outerSize;
123	    tiling->innerSize     = innerSize;
124	    tiling->dimSize       = dimSize;
125	    tiling->dtypeSize     = dtypeSize;
126	    tiling->numChunks     = K;
127	    tiling->tileLength    = tileLength;
128	    tiling->coreNum       = coreNum;
129	
130	    for (int64_t i = 0; i < K; ++i) {
131	        tiling->chunkSizes[i] = chunkSizes[i];
132	    }
133	    for (int64_t i = 0; i <= K; ++i) {
134	        tiling->cumChunkOffsets[i] = cumChunkOffsets[i];
135	        tiling->cumOutputOffsets[i] = cumOutputOffsets[i];
136	    }
137	
138	    auto tilingNpu = tilingCpu.to(at::kPrivateUse1);
139	
140	    // ---- 8. 启动 kernel (EXEC_KERNEL_CMD 参数均为左值) ----
141	    uint32_t blockDim = static_cast<uint32_t>(coreNum);
142	
143	    bool isHalf = (x.scalar_type() == at::kHalf ||
144	                   x.scalar_type() == at::kBFloat16);
145	
146	    if (isHalf) {
147	        EXEC_KERNEL_CMD(split_half, blockDim, x, output, tilingNpu);
148	    } else {
149	        EXEC_KERNEL_CMD(split_float, blockDim, x, output, tilingNpu);
150	    }
151	
152	    return output;
153	}
