17	#include "kernel_operator.h"
18	
19	using namespace AscendC;
20	
21	constexpr int64_t BUFFER_NUM = 2;
22	constexpr int64_t MAX_CHUNKS = 64;
23	
24	struct SplitTilingData {
25	    int64_t totalSegments;
26	    int64_t outerSize;
27	    int64_t innerSize;
28	    int64_t dimSize;
29	    int64_t dtypeSize;
30	
31	    int64_t numChunks;
32	    int64_t chunkSizes[MAX_CHUNKS];
33	    int64_t cumChunkOffsets[MAX_CHUNKS + 1];
34	    int64_t cumOutputOffsets[MAX_CHUNKS + 1];
35	
36	    int64_t tileLength;
37	    int64_t coreNum;
38	};
39	
40	template <typename T>
41	class SplitKernel {
42	public:
43	    __aicore__ inline SplitKernel() {}
44	
45	    __aicore__ inline void Init(GM_ADDR input, GM_ADDR output, GM_ADDR workspace);
46	    __aicore__ inline void Process();
47	
48	private:
49	    __aicore__ inline void CopySegment(int64_t inputOffset, int64_t outputOffset, int64_t count);
50	    __aicore__ inline int64_t FindChunk(int64_t dimIdx);
51	
52	private:
53	    TPipe pipe;
54	    TQue<TPosition::VECOUT, BUFFER_NUM> outQueue;
55	
56	    GlobalTensor<T> inputGm;
57	    GlobalTensor<T> outputGm;
58	
59	    SplitTilingData tiling_;
60	
61	    int64_t segStart_;
62	    int64_t segEnd_;
63	};
64	
65	template <typename T>
66	__aicore__ inline int64_t SplitKernel<T>::FindChunk(int64_t dimIdx) {
67	    for (int64_t c = 0; c < tiling_.numChunks; ++c) {
68	        if (dimIdx >= tiling_.cumChunkOffsets[c] &&
69	            dimIdx < tiling_.cumChunkOffsets[c + 1]) {
70	            return c;
71	        }
72	    }
73	    return tiling_.numChunks - 1;
74	}
