76	template <typename T>
77	__aicore__ inline void SplitKernel<T>::CopySegment(int64_t inputOffset,
78	                                                    int64_t outputOffset,
79	                                                    int64_t count) {
80	    int64_t tileCount = (count + tiling_.tileLength - 1) / tiling_.tileLength;
81	
82	    for (int64_t t = 0; t < tileCount; ++t) {
83	        int64_t curLen = tiling_.tileLength;
84	        if (t == tileCount - 1) {
85	            curLen = count - t * tiling_.tileLength;
86	        }
87	
88	        int64_t curLenBytes = curLen * sizeof(T);
89	
90	        // Step 1: Load from input GM into VECOUT buffer
91	        LocalTensor<T> bufLocal = outQueue.AllocTensor<T>();
92	
93	        DataCopyExtParams copyParams;
94	        copyParams.blockCount = 1;
95	        copyParams.blockLen   = static_cast<uint32_t>(curLenBytes);
96	        copyParams.srcStride  = 0;
97	        copyParams.dstStride  = 0;
98	
99	        DataCopyPadExtParams<T> padParams;
100	        padParams.isPad = false;
101	
102	        DataCopyPad(bufLocal,
103	                    inputGm[inputOffset + t * tiling_.tileLength],
104	                    copyParams,
105	                    padParams);
106	
107	        // Wait for GM->UB DMA, then synchronize via queue
108	        PipeBarrier<PIPE_ALL>();
109	        outQueue.EnQue<T>(bufLocal);
110	        LocalTensor<T> bufReady = outQueue.DeQue<T>();
111	
112	        // Step 2: Write to output GM from the same buffer
113	        DataCopyPad(outputGm[outputOffset + t * tiling_.tileLength],
114	                    bufReady,
115	                    copyParams);
116	
117	        outQueue.FreeTensor(bufReady);
118	    }
119	}
