121	template <typename T>
122	__aicore__ inline void SplitKernel<T>::Init(GM_ADDR input,
123	                                             GM_ADDR output,
124	                                             GM_ADDR workspace) {
125	    auto *ws = reinterpret_cast<__gm__ SplitTilingData *>(workspace);
126	    tiling_.totalSegments    = ws->totalSegments;
127	    tiling_.outerSize        = ws->outerSize;
128	    tiling_.innerSize        = ws->innerSize;
129	    tiling_.dimSize          = ws->dimSize;
130	    tiling_.dtypeSize        = ws->dtypeSize;
131	    tiling_.numChunks        = ws->numChunks;
132	    tiling_.tileLength       = ws->tileLength;
133	    tiling_.coreNum          = ws->coreNum;
134	
135	    for (int64_t i = 0; i < tiling_.numChunks; ++i) {
136	        tiling_.chunkSizes[i]       = ws->chunkSizes[i];
137	        tiling_.cumChunkOffsets[i]  = ws->cumChunkOffsets[i];
138	        tiling_.cumOutputOffsets[i] = ws->cumOutputOffsets[i];
139	    }
140	    tiling_.cumChunkOffsets[tiling_.numChunks]  = ws->cumChunkOffsets[tiling_.numChunks];
141	    tiling_.cumOutputOffsets[tiling_.numChunks] = ws->cumOutputOffsets[tiling_.numChunks];
142	
143	    inputGm.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(input));
144	    outputGm.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(output));
145	
146	    int64_t blockIdx = GetBlockIdx();
147	    int64_t segsPerCore = (tiling_.totalSegments + tiling_.coreNum - 1) / tiling_.coreNum;
148	    segStart_ = blockIdx * segsPerCore;
149	    segEnd_   = (segStart_ + segsPerCore < tiling_.totalSegments)
150	                  ? (segStart_ + segsPerCore)
151	                  : tiling_.totalSegments;
152	
153	    int64_t alignedTileBytes =
154	        ((tiling_.tileLength * tiling_.dtypeSize + 31) / 32) * 32;
155	    pipe.InitBuffer(outQueue, BUFFER_NUM, alignedTileBytes);
156	}
