158	template <typename T>
159	__aicore__ inline void SplitKernel<T>::Process() {
160	    if (tiling_.totalSegments <= 0) return;
161	    if (segStart_ >= segEnd_) return;
162	
163	    for (int64_t seg = segStart_; seg < segEnd_; ++seg) {
164	        int64_t outerIdx = seg / tiling_.dimSize;
165	        int64_t dimIdx   = seg % tiling_.dimSize;
166	
167	        int64_t chunkIdx    = FindChunk(dimIdx);
168	        int64_t localDimIdx = dimIdx - tiling_.cumChunkOffsets[chunkIdx];
169	
170	        int64_t inputOffset = seg * tiling_.innerSize;
171	        int64_t outputOffset = tiling_.cumOutputOffsets[chunkIdx] +
172	            (outerIdx * tiling_.chunkSizes[chunkIdx] + localDimIdx) *
173	                tiling_.innerSize;
174	
175	        CopySegment(inputOffset, outputOffset, tiling_.innerSize);
176	    }
177	}
