// ============================================================
// Split 算子 op_kernel
// 沿指定维度将输入 tensor 拆分为多个 chunk，按 segment (innerSize) 粒度搬移
// 使用 VECOUT 单队列流水模式
// ============================================================

#include "kernel_operator.h"

using namespace AscendC;

constexpr int64_t BUFFER_NUM = 2;
constexpr int64_t MAX_CHUNKS = 64;

struct SplitTilingData {
    int64_t totalSegments;
    int64_t outerSize;
    int64_t innerSize;
    int64_t dimSize;
    int64_t dtypeSize;

    int64_t numChunks;
    int64_t chunkSizes[MAX_CHUNKS];
    int64_t cumChunkOffsets[MAX_CHUNKS + 1];
    int64_t cumOutputOffsets[MAX_CHUNKS + 1];

    int64_t tileLength;
    int64_t coreNum;
};

template <typename T>
class SplitKernel {
public:
    __aicore__ inline SplitKernel() {}

    __aicore__ inline void Init(GM_ADDR input, GM_ADDR output, GM_ADDR workspace);
    __aicore__ inline void Process();

private:
    __aicore__ inline void CopySegment(int64_t inputOffset, int64_t outputOffset, int64_t count);
    __aicore__ inline int64_t FindChunk(int64_t dimIdx);

private:
    TPipe pipe;
    TQue<TPosition::VECOUT, BUFFER_NUM> outQueue;

    GlobalTensor<T> inputGm;
    GlobalTensor<T> outputGm;

    SplitTilingData tiling_;

    int64_t segStart_;
    int64_t segEnd_;
};

template <typename T>
__aicore__ inline int64_t SplitKernel<T>::FindChunk(int64_t dimIdx) {
    for (int64_t c = 0; c < tiling_.numChunks; ++c) {
        if (dimIdx >= tiling_.cumChunkOffsets[c] &&
            dimIdx < tiling_.cumChunkOffsets[c + 1]) {
            return c;
        }
    }
    return tiling_.numChunks - 1;
}

template <typename T>
__aicore__ inline void SplitKernel<T>::CopySegment(int64_t inputOffset,
                                                    int64_t outputOffset,
                                                    int64_t count) {
    int64_t tileCount = (count + tiling_.tileLength - 1) / tiling_.tileLength;

    for (int64_t t = 0; t < tileCount; ++t) {
        int64_t curLen = tiling_.tileLength;
        if (t == tileCount - 1) {
            curLen = count - t * tiling_.tileLength;
        }

        int64_t curLenBytes = curLen * sizeof(T);

        // Step 1: Load from input GM into VECOUT buffer
        LocalTensor<T> bufLocal = outQueue.AllocTensor<T>();

        DataCopyExtParams copyParams;
        copyParams.blockCount = 1;
        copyParams.blockLen   = static_cast<uint32_t>(curLenBytes);
        copyParams.srcStride  = 0;
        copyParams.dstStride  = 0;

        DataCopyPadExtParams<T> padParams;
        padParams.isPad = false;

        DataCopyPad(bufLocal,
                    inputGm[inputOffset + t * tiling_.tileLength],
                    copyParams,
                    padParams);

        // Wait for GM->UB DMA, then synchronize via queue
        PipeBarrier<PIPE_ALL>();
        outQueue.EnQue<T>(bufLocal);
        LocalTensor<T> bufReady = outQueue.DeQue<T>();

        // Step 2: Write to output GM from the same buffer
        DataCopyPad(outputGm[outputOffset + t * tiling_.tileLength],
                    bufReady,
                    copyParams);

        outQueue.FreeTensor(bufReady);
    }
}

template <typename T>
__aicore__ inline void SplitKernel<T>::Init(GM_ADDR input,
                                             GM_ADDR output,
                                             GM_ADDR workspace) {
    auto *ws = reinterpret_cast<__gm__ SplitTilingData *>(workspace);
    tiling_.totalSegments    = ws->totalSegments;
    tiling_.outerSize        = ws->outerSize;
    tiling_.innerSize        = ws->innerSize;
    tiling_.dimSize          = ws->dimSize;
    tiling_.dtypeSize        = ws->dtypeSize;
    tiling_.numChunks        = ws->numChunks;
    tiling_.tileLength       = ws->tileLength;
    tiling_.coreNum          = ws->coreNum;

    for (int64_t i = 0; i < tiling_.numChunks; ++i) {
        tiling_.chunkSizes[i]       = ws->chunkSizes[i];
        tiling_.cumChunkOffsets[i]  = ws->cumChunkOffsets[i];
        tiling_.cumOutputOffsets[i] = ws->cumOutputOffsets[i];
    }
    tiling_.cumChunkOffsets[tiling_.numChunks]  = ws->cumChunkOffsets[tiling_.numChunks];
    tiling_.cumOutputOffsets[tiling_.numChunks] = ws->cumOutputOffsets[tiling_.numChunks];

    inputGm.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(input));
    outputGm.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(output));

    int64_t blockIdx = GetBlockIdx();
    int64_t segsPerCore = (tiling_.totalSegments + tiling_.coreNum - 1) / tiling_.coreNum;
    segStart_ = blockIdx * segsPerCore;
    segEnd_   = (segStart_ + segsPerCore < tiling_.totalSegments)
                  ? (segStart_ + segsPerCore)
                  : tiling_.totalSegments;

    int64_t alignedTileBytes =
        ((tiling_.tileLength * tiling_.dtypeSize + 31) / 32) * 32;
    pipe.InitBuffer(outQueue, BUFFER_NUM, alignedTileBytes);
}

template <typename T>
__aicore__ inline void SplitKernel<T>::Process() {
    if (tiling_.totalSegments <= 0) return;
    if (segStart_ >= segEnd_) return;

    for (int64_t seg = segStart_; seg < segEnd_; ++seg) {
        int64_t outerIdx = seg / tiling_.dimSize;
        int64_t dimIdx   = seg % tiling_.dimSize;

        int64_t chunkIdx    = FindChunk(dimIdx);
        int64_t localDimIdx = dimIdx - tiling_.cumChunkOffsets[chunkIdx];

        int64_t inputOffset = seg * tiling_.innerSize;
        int64_t outputOffset = tiling_.cumOutputOffsets[chunkIdx] +
            (outerIdx * tiling_.chunkSizes[chunkIdx] + localDimIdx) *
                tiling_.innerSize;

        CopySegment(inputOffset, outputOffset, tiling_.innerSize);
    }
}

// =========================== Kernel 入口 ============================

extern "C" __global__ __aicore__ void split_half(GM_ADDR input,
                                                   GM_ADDR output,
                                                   GM_ADDR workspace) {
    if (sizeof(SplitTilingData) > 0) {
        SplitKernel<half> op;
        op.Init(input, output, workspace);
        op.Process();
    }
}

extern "C" __global__ __aicore__ void split_float(GM_ADDR input,
                                                    GM_ADDR output,
                                                    GM_ADDR workspace) {
    if (sizeof(SplitTilingData) > 0) {
        SplitKernel<float> op;
        op.Init(input, output, workspace);
        op.Process();
    }
}
