// ============================================================
// Split 算子 op_host
// 将输入沿 dim 拆分为 K 个 chunk，输出为 1D flat 拼接
// ============================================================

#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"
#include "aclrtlaunch_split_half.h"
#include "aclrtlaunch_split_float.h"

namespace ascend_kernel {

constexpr int64_t MAX_CHUNKS = 64;

struct SplitTilingData {
    int64_t totalSegments;
    int64_t outerSize;
    int64_t innerSize;
    int64_t dimSize;
    int64_t dtypeSize;

    int64_t numChunks;
    int64_t chunkSizes[MAX_CHUNKS];
    int64_t cumChunkOffsets[MAX_CHUNKS + 1];
    int64_t cumOutputOffsets[MAX_CHUNKS + 1];

    int64_t tileLength;
    int64_t coreNum;
};

at::Tensor split(const at::Tensor &x,
                 at::IntArrayRef split_sizes,
                 int64_t dim) {
    // ---- 1. 参数校验 ----
    TORCH_CHECK(x.device().is_privateuseone(), "split: x must be on NPU device");
    TORCH_CHECK(x.is_contiguous(), "split: x must be contiguous");
    TORCH_CHECK(x.scalar_type() == at::kFloat ||
                x.scalar_type() == at::kHalf ||
                x.scalar_type() == at::kBFloat16,
                "split: only float32, float16, bfloat16 are supported");

    int64_t ndim = x.dim();
    if (dim < 0) dim += ndim;
    TORCH_CHECK(dim >= 0 && dim < ndim,
                "split: dim out of range, got dim=", dim);

    int64_t K = split_sizes.size();
    TORCH_CHECK(K <= MAX_CHUNKS,
                "split: too many chunks (", K, "), max is ", MAX_CHUNKS);

    // ---- 2. 计算维度参数 ----
    int64_t outerSize = 1;
    for (int64_t i = 0; i < dim; ++i) {
        outerSize *= x.size(i);
    }
    int64_t dimSize = x.size(dim);
    int64_t innerSize = 1;
    for (int64_t i = dim + 1; i < ndim; ++i) {
        innerSize *= x.size(i);
    }
    int64_t totalSegments = outerSize * dimSize;
    int64_t totalElements = totalSegments * innerSize;

    // ---- 3. 计算 chunk 累计偏移 ----
    int64_t chunkSizes[MAX_CHUNKS] = {0};
    int64_t cumChunkOffsets[MAX_CHUNKS + 1] = {0};
    int64_t cumOutputOffsets[MAX_CHUNKS + 1] = {0};

    int64_t sumChunk = 0;
    int64_t sumOutput = 0;
    for (int64_t i = 0; i < K; ++i) {
        int64_t sz = split_sizes[i];
        chunkSizes[i] = sz;
        cumChunkOffsets[i] = sumChunk;
        cumOutputOffsets[i] = sumOutput;
        sumChunk += sz;
        sumOutput += outerSize * sz * innerSize;
    }
    cumChunkOffsets[K] = sumChunk;
    cumOutputOffsets[K] = sumOutput;

    TORCH_CHECK(sumChunk == dimSize,
                "split: sum of split_sizes (", sumChunk,
                ") != dim size (", dimSize, ")");

    // ---- 4. 平台参数 ----
    auto platform = platform_ascendc::PlatformAscendCManager::GetInstance();
    int64_t coreNum = static_cast<int64_t>(platform->GetCoreNumAiv());
    uint64_t ubSize;
    platform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);

    int64_t dtypeSize = static_cast<int64_t>(x.element_size());

    // ---- 5. Tiling 计算 ----
    // bufferCoefficient = 2: VECOUT only, double buffer, no compute buffer
    int64_t bufferCoefficient = 2;
    int64_t alignElements = 32 / dtypeSize;
    int64_t maxTileElements = static_cast<int64_t>(ubSize) / (bufferCoefficient * dtypeSize);
    int64_t tileLength = (maxTileElements / alignElements) * alignElements;
    if (tileLength < alignElements) tileLength = alignElements;

    // ---- 6. 创建输出 tensor (1D flat) ----
    auto output = at::empty({totalElements}, x.options());

    // ---- 7. 填充 workspace (tiling data) ----
    auto tilingCpu = at::empty(
        {static_cast<int64_t>(sizeof(SplitTilingData))},
        at::device(at::kCPU).dtype(at::kByte));
    auto *tiling = reinterpret_cast<SplitTilingData *>(tilingCpu.data_ptr());

    tiling->totalSegments = totalSegments;
    tiling->outerSize     = outerSize;
    tiling->innerSize     = innerSize;
    tiling->dimSize       = dimSize;
    tiling->dtypeSize     = dtypeSize;
    tiling->numChunks     = K;
    tiling->tileLength    = tileLength;
    tiling->coreNum       = coreNum;

    for (int64_t i = 0; i < K; ++i) {
        tiling->chunkSizes[i] = chunkSizes[i];
    }
    for (int64_t i = 0; i <= K; ++i) {
        tiling->cumChunkOffsets[i] = cumChunkOffsets[i];
        tiling->cumOutputOffsets[i] = cumOutputOffsets[i];
    }

    auto tilingNpu = tilingCpu.to(at::kPrivateUse1);

    // ---- 8. 启动 kernel (EXEC_KERNEL_CMD 参数均为左值) ----
    uint32_t blockDim = static_cast<uint32_t>(coreNum);

    bool isHalf = (x.scalar_type() == at::kHalf ||
                   x.scalar_type() == at::kBFloat16);

    if (isHalf) {
        EXEC_KERNEL_CMD(split_half, blockDim, x, output, tilingNpu);
    } else {
        EXEC_KERNEL_CMD(split_float, blockDim, x, output, tilingNpu);
    }

    return output;
}

